// JNI - FFI boundary demo (simulated)
var nativeLib = { add: function(a, b) { return a + b; } }; // "C" side
function ffiCall(fn) {
  return function() {
    var args = Array.prototype.slice.call(arguments);
    var t0 = Date.now();
    var r = fn.apply(null, args);
    return { result: r, boundary_us: (Date.now() - t0) * 1000 };
  };
}
var add = ffiCall(nativeLib.add);
var out = add(20, 22);
console.log("Framework: JNI | Bridges: Java <-> C/C++");
console.log("add(20,22) across boundary = " + out.result);
console.log("Boundary crossed -> PASS");

